<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRoute } from 'vue-router'
import { showToast } from 'vant'
import { session } from '../session'
import { visibleAssets, assetLogs, statusText, moveAsset } from '../stores/warehouse'
import '../warehouse.css'
const route = useRoute(); const asset = computed(() => visibleAssets.value.find(row => row.id === Number(route.params.id)))
const open = ref(false); const person = ref(''); const error = ref(''); const busy = ref(false); const expected = ref('')
const taking = computed(() => open.value ? expected.value === 'in_stock' : asset.value?.status === 'in_stock')
const logs = computed(() => assetLogs.value.filter(log => log.asset_id === asset.value?.id).slice(0, 50))
function openMove() { if (!asset.value || asset.value.review_status !== 'approved') return; person.value = ''; error.value = ''; expected.value = asset.value.status; open.value = true }
function save() { if (!asset.value || busy.value) return; busy.value = true; error.value = ''; try { if (asset.value.status !== expected.value) throw new Error('资产状态已变化，请关闭后重新核对'); moveAsset(asset.value.id, taking.value ? 'take' : 'return', person.value); open.value = false; showToast('领还已登记，仅保存在本机演示') } catch (e) { error.value = e instanceof Error ? e.message : '登记失败，请重试' } finally { busy.value = false } }
</script>
<template>
  <div v-if="asset" class="page warehouse-page"><div class="item-intro"><van-tag plain>{{ asset.category || '未分类' }}</van-tag><h1>{{ asset.name }}</h1><p>{{ asset.code || '未填编号' }} · {{ asset.location || '未填位置' }}</p></div><van-cell-group inset><van-cell title="审核状态"><template #value><van-tag plain :type="asset.review_status === 'approved' ? 'success' : asset.review_status === 'rejected' ? 'danger' : 'warning'">{{ statusText(asset.review_status) }}</van-tag></template></van-cell><van-cell title="领用状态" :value="asset.status === 'taken' ? '已领用' : '在库'" /><van-cell title="资产编号" :value="asset.code || '未填写'" /><van-cell title="分类" :value="asset.category || '未填写'" /><van-cell title="存放位置" :value="asset.location || '未填写'" /><van-cell v-if="asset.status === 'taken'" title="当前领用人" :value="asset.holder" /><van-cell v-if="asset.taken_at" title="领用时间" :value="asset.taken_at" /><van-cell title="登记人" :value="asset.created_name" /><van-cell v-if="asset.note" title="备注" :label="asset.note" /></van-cell-group><van-notice-bar v-if="asset.review_status !== 'approved'" wrapable :scrollable="false" class="warehouse-gap" :text="asset.review_status === 'pending' ? '资产待审核，通过后才能登记领用或归还。' : `已退回：${asset.reject_reason || '请联系管理员了解原因'}`" /><van-button v-if="asset.review_status === 'approved'" block type="primary" class="secondary-wide" @click="openMove">{{ taking ? '登记领用' : '登记归还' }}</van-button><van-button v-else-if="session.role === 'admin' && asset.review_status === 'pending'" block plain type="primary" class="secondary-wide" to="/reviews">前往审核中心</van-button><p class="section-caption">领用和归还按实际人员姓名登记，不限于当前登录账号本人。仅用于本机演示。</p>
    <section class="section"><div class="section-heading"><h2>最近领还记录</h2><span class="muted">最多50条</span></div><van-cell-group v-if="logs.length" inset><van-cell v-for="log in logs" :key="log.id" :title="`${log.action === 'take' ? '领用' : '归还'} · ${log.person}`" :label="`${log.at}${log.note ? `\n${log.note}` : ''}`" /></van-cell-group><van-empty v-else description="暂无本机领还记录" /></section>
    <van-popup v-model:show="open" position="bottom" round closeable safe-area-inset-bottom :close-on-click-overlay="false" class="move-popup"><h2 class="popup-title">{{ taking ? '登记领用' : '登记归还' }}</h2><p class="popup-subtitle">{{ asset.name }}{{ !taking ? ` · 当前领用人：${asset.holder}` : '' }}</p><p v-if="error" class="warehouse-error" role="alert">{{ error }}</p><van-form @submit="save"><van-field v-model="person" :label="taking ? '领用人' : '归还人'" name="person" required maxlength="60" placeholder="填写实际人员姓名" :rules="[{ validator: (v: string) => !!v.trim() && v.trim().length <= 60, message: '请填写1至60字的人员姓名' }]" /><div class="popup-actions"><van-button block plain native-type="button" @click="open = false">取消</van-button><van-button block type="primary" native-type="submit" :loading="busy">{{ taking ? '确认领用' : '确认归还' }}</van-button></div></van-form></van-popup>
  </div><div v-else class="page"><van-empty description="资产不存在或当前账号无权查看"><van-button type="primary" to="/assets">返回资产列表</van-button></van-empty></div>
</template>
